/**
 * Slugger that counts duplicates per document, equivalent to `new GithubSlugger()`.
 *
 * The second identical slug gets `-1`, the third `-2` and so on.
 */
final class Slugger
{
    /** @var array<string, int> */
    private array $occurrences = [];

    public function slug(string $value, bool $maintainCase = false): string
    {
        $result = Slug::make($value, $maintainCase);
        $original = $result;

        while (array_key_exists($result, $this->occurrences)) {
            $this->occurrences[$original]++;
            $result = $original . '-' . $this->occurrences[$original];
        }

        $this->occurrences[$result] = 0;

        return $result;
    }

    public function reset(): void
    {
        $this->occurrences = [];
    }
}
